import { svgToImage } from "weizhi:svg-raster";
export default await svgToImage({
  svgPath: 'logo.svg',
  outputPath: 'out/logo.png',
  width: 800,
  height: 400,
  format: 'png'
});

import { probe, resize } from "weizhi:image";
const meta = await probe("imports/photo.jpg");
export default await resize({ path: "imports/photo.jpg", output: "out/small.jpg", maxEdge: 2048 });

const { exportVideo } = await import("weizhi:video");
const D = 300;
export default await exportVideo({ width: 720, height: 1280, tracks: [{ type: "image", clips: [
  { src: "a.jpg", startMs: 0, durationMs: 1000 },
  { src: "b.jpg", startMs: 700, durationMs: 1000, transition: { type: "crossfade", durationMs: D } }
]}], output: "out.mp4" });
